<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import Icon from './Icon.vue'
import JsonlImportGuide from './JsonlImportGuide.vue'
import ImportDropZone from './ImportDropZone.vue'
import {importNotice} from './importNotice'
import type {TeamState,ImportKind} from './types'
const props=defineProps<{team?:TeamState;mode:string;busy:string}>()
const emit=defineEmits<{action:[method:string,params:Record<string,unknown>,message:string];error:[message:string];notice:[message:string];pending:[value:boolean]}>()
const member=ref(''),newName=ref(''),rename=ref(''),text=ref(''),inputMode=ref('files'),period=ref('all')
const importing=ref(false),exporting=ref(false),selected=ref(''),shown=ref(20)
const assignments=ref<Record<string,{member:string;plan:string}>>({})
const colors=['#67618e','#3e7472','#80625c','#837250','#52718b','#755e78','#63785e','#545e83','#86664d','#78698a','#48727a','#79794f','#7b5b6e','#567066','#6e6f89','#817153','#577087','#7b655f','#697653','#69677f']
function shade(hex:string,amount:number){return '#'+[1,3,5].map(i=>{const v=parseInt(hex.slice(i,i+2),16);return Math.round(amount>=0?v+(255-v)*amount:v*(1+amount)).toString(16).padStart(2,'0')}).join('')}
const members=computed(()=>props.team?.members || [])
let knownIds=new Set<string>()
watch(()=>members.value.map(m=>m.id).join('|'),()=>{const added=members.value.find(m=>!knownIds.has(m.id));if(added){if(knownIds.size)member.value=added.id;if(newName.value.trim()===added.name)newName.value=''}if(!members.value.some(m=>m.id===member.value))member.value=members.value[0]?.id || '';knownIds=new Set(members.value.map(m=>m.id))},{immediate:true})
watch([()=>member.value,()=>members.value.find(m=>m.id===member.value)?.name],()=>{rename.value=members.value.find(m=>m.id===member.value)?.name || ''},{immediate:true})
const report=computed(()=>props.team?.plans[props.mode]?.[period.value] || {total:0,members:[]})
const locked=computed(()=>!!props.busy || importing.value || exporting.value || !!props.team?.error)
const format=(n:number)=>n.toLocaleString('zh-CN')
const slices=computed(()=>{
 let angle=-Math.PI/2
 return report.value.members.map((m,i)=>{const from=angle;angle+=report.value.total?m.tokens/report.value.total*Math.PI*2:0;const x1=160+132*Math.cos(from),y1=160+132*Math.sin(from),x2=160+132*Math.cos(angle),y2=160+132*Math.sin(angle),mid=(from+angle)/2;return {...m,color:colors[i%colors.length],full:m.tokens===report.value.total,labelX:160+106*Math.cos(mid),labelY:160+106*Math.sin(mid),path:`M160 160L${x1} ${y1}A132 132 0 ${angle-from>Math.PI?1:0} 1 ${x2} ${y2}Z`}})
})
const focused=computed(()=>report.value.members.find(m=>m.id===selected.value))
const sessions=computed(()=>props.team?.sessions.filter(s=>s.plan===props.mode) || [])
function assignment(key:string,oldMember:string,oldPlan:string){return assignments.value[key] || {member:oldMember,plan:oldPlan}}
function setAssignment(key:string,field:'member'|'plan',value:string,oldMember:string,oldPlan:string){assignments.value[key]={...assignment(key,oldMember,oldPlan),[field]:value}}
async function importFiles(kind:ImportKind='files'){
 importing.value=true;emit('pending',true)
 try{const result=await window.aiLink.importTeam(member.value,props.mode,kind);if(result)emit('notice',importNotice(result))}catch(error){emit('error',String(error))}finally{importing.value=false;emit('pending',false)}
}
async function importDropped(files:File[]){
 if(locked.value||!member.value)return
 importing.value=true;emit('pending',true)
 try{const result=await window.aiLink.importDropped(files,{kind:'team',memberId:member.value,plan:props.mode});if(result)emit('notice',importNotice(result))}catch(error){emit('error',String(error))}finally{importing.value=false;emit('pending',false)}
}
async function importText(){
 if(new TextEncoder().encode(text.value).length>64000)return emit('error','粘贴内容超过 64 KB，请使用文件导入。')
 importing.value=true;emit('pending',true)
 try{const result=await window.aiLink.request<{tokens:number;skipped:number;malformed:number}>('team.import.text',{memberId:member.value,plan:props.mode,text:text.value});emit('notice',`新增 ${format(result.tokens)} tokens；忽略 ${result.skipped+result.malformed} 条无效记录。重复用量不再计入。`)}catch(error){emit('error',String(error))}finally{importing.value=false;emit('pending',false)}
}
async function exportChart(format:'svg'|'csv'){
 exporting.value=true;emit('pending',true)
 try{if(await window.aiLink.exportTeam(props.mode,period.value,format))emit('notice',format==='svg'?'多人用量饼图已导出。':'多人用量数据已导出。')}catch(error){emit('error',String(error))}finally{exporting.value=false;emit('pending',false)}
}
</script>
<template><section class="team-workspace">
 <div class="section-heading"><div><span class="eyebrow muted">PEOPLE & USAGE · {{ mode.toUpperCase() }}</span><h3>多人用量报表</h3><p>为每个人输入对话记录，比较已记录 tokens 的分布。</p></div><div class="button-row"><button class="btn secondary" :disabled="locked || !report.total" @click="exportChart('svg')"><Icon name="download" :size="16"/>导出饼图</button><button class="btn ghost" :disabled="locked || !report.total" @click="exportChart('csv')">CSV 数据</button></div></div>
 <div v-if="team?.error" class="notice warning" role="alert"><Icon name="info"/><span>{{ team.error }}</span></div>
 <section class="panel team-import-panel"><div class="section-heading"><div><h3>添加成员与记录</h3><p>与个人守护档案分开保存；导入记录不会操作 Codex 对话。</p></div><span class="badge subtle">{{ members.length }} / 20 位成员</span></div>
  <form class="team-member-create" @submit.prevent="emit('action','team.member.create',{name:newName.trim()},'成员已添加，可为其导入记录。')"><label class="field-label" for="team-new-name">成员名称<input id="team-new-name" v-model="newName" maxlength="24" placeholder="例如：张三" :disabled="locked"></label><button class="btn secondary" :disabled="locked || !newName.trim() || members.length>=20" type="submit"><Icon name="users" :size="16"/>添加成员</button></form>
  <div class="team-import-options"><label class="field-label" for="team-member">本次记录归属<select id="team-member" v-model="member" :disabled="locked || !members.length"><option v-if="!members.length" value="">先添加成员</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><div class="team-plan-note"><span class="badge purple">{{ mode.toUpperCase() }}</span><small>与上方计划选择一致<br>按所选模式归类，不验证历史套餐</small></div><div class="segmented team-input-mode" role="group" aria-label="记录输入方式"><button :class="{selected:inputMode==='files'}" :disabled="locked" @click="inputMode='files'">导入文件</button><button :class="{selected:inputMode==='text'}" :disabled="locked" @click="inputMode='text'">粘贴记录</button></div></div>
  <ImportDropZone v-if="inputMode==='files'" class="team-file-import" :target="`${members.find(m=>m.id===member)?.name || '待选成员'} · ${mode.toUpperCase()}`" :disabled="locked || !member" :busy="importing" @choose="importFiles" @files="importDropped"/>
  <div v-else class="team-text-import"><label class="field-label" for="team-records">粘贴 Codex JSONL 用量记录<span>最多 64 KB</span></label><textarea id="team-records" v-model="text" rows="6" maxlength="64000" spellcheck="false" placeholder="粘贴包含 session_meta 和 event_msg / token_count 的 JSONL 记录…" :disabled="locked"></textarea><div class="composer-footer"><small>内容仅在本机解析，报表不保存正文。</small><button class="btn primary" :disabled="locked || !member || !text.trim()" @click="importText"><Icon name="check" :size="16"/>统计此成员</button></div></div>
  <JsonlImportGuide context="team" :mode="mode"/>
 </section>
 <div class="team-chart-heading"><div class="segmented team-period" role="group" aria-label="多人报表时间范围"><button v-for="p in [{id:'all',name:'全部历史'},{id:'primary',name:'近 5 小时'},{id:'secondary',name:'近 7 天'}]" :key="p.id" :class="{selected:period===p.id}" :aria-pressed="period===p.id" @click="period=p.id">{{ p.name }}</button></div><span class="micro-copy">仅包含已导入记录 · {{ mode.toUpperCase() }}</span></div>
 <div class="team-report-grid"><article class="panel team-pie-panel"><div class="section-heading"><div><span class="eyebrow muted">TOKEN DISTRIBUTION</span><h3>成员用量占比</h3></div><span class="badge subtle">{{ report.members.filter(m=>m.tokens>0).length }} 位有用量</span></div><div class="team-pie-container"><svg v-if="report.total" class="team-pie" viewBox="0 0 320 320" role="group" :aria-label="`多人用量饼图，合计${report.total} tokens`"><defs><mask id="team-ring-cut" maskUnits="userSpaceOnUse" x="0" y="0" width="320" height="320"><rect width="320" height="320" fill="white"/><circle class="pie-mask-cut" cx="160" cy="160" r="80" fill="black"/></mask><radialGradient id="team-center-well" cx="40%" cy="35%" r="75%"><stop offset="0%" class="pie-well-start"/><stop offset="100%" class="pie-well-end"/></radialGradient><linearGradient id="team-rim-light" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#b8c7d5" stop-opacity=".19"/><stop offset="45%" stop-color="#b8c7d5" stop-opacity=".02"/><stop offset="100%" stop-color="#080f1b" stop-opacity=".28"/></linearGradient><linearGradient v-for="slice in slices" :id="`team-slice-${slice.id}`" :key="slice.id" x1="10%" y1="0%" x2="90%" y2="100%"><stop offset="0%" :stop-color="shade(slice.color,.055)"/><stop offset="55%" :stop-color="slice.color"/><stop offset="100%" :stop-color="shade(slice.color,-.16)"/></linearGradient></defs><circle cx="160" cy="160" r="106" class="pie-track"/><g mask="url(#team-ring-cut)"><template v-for="slice in slices" :key="slice.id"><g v-if="slice.tokens>0" class="pie-segment" tabindex="0" role="button" :aria-label="`${slice.name}，${slice.tokens} tokens，${slice.share.toFixed(1)}%`" :class="{dimmed:!!selected&&selected!==slice.id}" @mouseenter="selected=slice.id" @mouseleave="selected=''" @focus="selected=slice.id" @blur="selected=''" @click="selected=selected===slice.id?'':slice.id" @keydown.enter="selected=slice.id"><circle v-if="slice.full" cx="160" cy="160" r="132" :fill="`url(#team-slice-${slice.id})`"/><path v-else :d="slice.path" :fill="`url(#team-slice-${slice.id})`"/></g></template></g><circle cx="160" cy="160" r="132.5" class="pie-outer-rim"/><circle cx="160" cy="160" r="79.5" fill="url(#team-center-well)" class="pie-center-well"/><circle cx="160" cy="160" r="80.5" class="pie-inner-rim"/><g class="pie-labels" aria-hidden="true"><text v-for="slice in slices.filter(s=>s.share>=7)" :key="slice.id" :x="slice.labelX" :y="slice.labelY" class="pie-slice-label">{{ slice.share.toFixed(1) }}%</text></g><g class="pie-center-content" aria-hidden="true"><text x="160" y="135" class="pie-center-kicker">OBSERVED TOKENS</text><text x="160" y="171" class="pie-center-value" :style="{fontSize:Math.max(12,Math.min(28,250/format(report.total).length))+'px'}">{{ format(report.total) }}</text><path d="M143 189H177" class="pie-center-rule"/><text x="160" y="210" class="pie-center-unit">tokens</text></g></svg><div v-else class="team-pie-empty"><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="57"/></svg><span>此窗口暂无成员用量</span><small>添加成员并导入记录后显示真实比例。</small></div></div><div class="team-total" :class="{'has-focus':!!focused}"><span>{{ focused?focused.name:'成员分布' }}</span><strong v-if="focused">{{ format(focused.tokens) }} <small>tokens</small></strong><span v-if="focused">{{ focused.share.toFixed(1) }}% · {{ focused.sessions }} 个对话</span><span v-else>悬停或用 Tab 键查看明细</span></div></article>
 <article class="panel team-members-panel"><div class="section-heading"><div><span class="eyebrow muted">BY PERSON</span><h3>成员明细</h3></div><span class="badge subtle">{{ report.total.toLocaleString() }} tokens</span></div><div v-if="!members.length" class="empty-state"><Icon name="users" :size="30"/><strong>先添加第一位成员</strong><p>每个人的记录独立归属，再汇总为饼图。</p></div><div v-else class="team-member-list"><button v-for="(m,index) in report.members" :key="m.id" class="team-member-row" :class="{highlighted:selected===m.id}" :style="{'--member-color':colors[index%colors.length]}" @mouseenter="selected=m.id" @mouseleave="selected=''" @focus="selected=m.id" @blur="selected=''" @click="member=m.id"><span class="member-color"></span><span class="team-member-name"><strong>{{ m.name }}</strong><small>{{ m.sessions }} 个对话</small></span><span class="team-member-tokens"><strong>{{ format(m.tokens) }}</strong><small>{{ m.share.toFixed(1) }}%</small></span><span class="member-share-bar"><i :style="{width:`${m.share}%`}"></i></span></button></div><form v-if="member" class="member-rename" @submit.prevent="emit('action','team.member.rename',{memberId:member,name:rename.trim()},'成员名称已更新。')"><label class="sr-only" for="team-rename">修改当前成员名称</label><input id="team-rename" v-model="rename" maxlength="24" :disabled="locked" placeholder="当前成员名称"><button class="btn ghost" :disabled="locked || !rename.trim() || rename.trim()===members.find(m=>m.id===member)?.name">保存名称</button></form></article></div>
 <details class="panel team-sessions"><summary><span>记录归属 <span class="count-badge">{{ sessions.length }}</span></span><small>调整误分配的成员或套餐模式</small><Icon name="down" :size="17"/></summary><div v-if="!sessions.length" class="benchmark-empty">当前模式尚未导入对话记录。</div><div v-for="session in sessions.slice(0,shown)" :key="session.key" class="team-session-row"><div><strong>对话 {{ session.key.slice(0,8) }}</strong><small>{{ format(session.tokens) }} tokens · {{ session.updated?new Date(session.updated*1000).toLocaleDateString('zh-CN'):'无新增用量' }}</small></div><select :value="assignment(session.key,session.member,session.plan).member" :disabled="locked" :aria-label="`对话 ${session.key.slice(0,8)} 的成员`" @change="setAssignment(session.key,'member',($event.target as HTMLSelectElement).value,session.member,session.plan)"><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select><select :value="assignment(session.key,session.member,session.plan).plan" :disabled="locked" :aria-label="`对话 ${session.key.slice(0,8)} 的模式`" @change="setAssignment(session.key,'plan',($event.target as HTMLSelectElement).value,session.member,session.plan)"><option value="plus">PLUS</option><option value="pro">PRO</option></select><button class="btn secondary" :disabled="locked || (assignment(session.key,session.member,session.plan).member===session.member && assignment(session.key,session.member,session.plan).plan===session.plan)" @click="emit('action','team.assign',{sessionKey:session.key,memberId:assignment(session.key,session.member,session.plan).member,plan:assignment(session.key,session.member,session.plan).plan},'记录归属已调整，用量不会重复或丢失。')">应用归属</button></div><button v-if="sessions.length>shown" class="btn ghost" @click="shown+=20">再显示 20 个对话</button></details>
 <p class="micro-copy section-note"><Icon name="info" :size="14"/>多人报表使用独立导入账本，保留全部已导入时间；不会据此推算账号额度，也不会改变个人额度守护的上限。</p>
</section></template>
